type Operacion =
  | { op: 'on'; evento: string; id: string }
  | { op: 'off'; evento: string; id: string }
  | { op: 'emit'; evento: string; dato: unknown };

export class EventEmitter {
  // tu código: on, off, emit
  on(evento: string, id: string, escuchador: (dato: unknown) => void) {
    // tu código
  }
  off(evento: string, id: string) {
    // tu código
  }
  emit(evento: string, dato: unknown) {
    // tu código
  }
}

// La función probarEventEmitter la usa el runner: aplica una lista de
// operaciones sobre un único EventEmitter y devuelve el registro de
// disparos { id, dato } en el orden en que ocurrieron.
export function probarEventEmitter(operaciones: Operacion[]): { id: string; dato: unknown }[] {
  const emisor = new EventEmitter();
  const registro: { id: string; dato: unknown }[] = [];
  for (const operacion of operaciones) {
    if (operacion.op === 'on') {
      emisor.on(operacion.evento, operacion.id, (dato) => registro.push({ id: operacion.id, dato }));
    } else if (operacion.op === 'off') {
      emisor.off(operacion.evento, operacion.id);
    } else {
      emisor.emit(operacion.evento, operacion.dato);
    }
  }
  return registro;
}
